'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {settings:'M4 7h16M4 17h16M8 4v6M16 14v6',layers:'m12 3 10 6-10 6L2 9zM2 14l10 6 10-6',board:'M3 3h7v7H3zM14 3h7v4h-7zM14 11h7v10h-7zM3 14h7v7H3z',history:'M3 11a9 9 0 1 1 2.6 7M3 4v7h7M12 7v5l3 2',chart:'M4 20V11M10 20V5M16 20V8M22 20H2',monitor:'M3 4h18v12H3zM8 21h8M12 16v5',plus:'M12 5v14M5 12h14',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',calendar:'M4 5h16v16H4zM4 10h16M8 3v4M16 3v4',left:'m14 6-6 6 6 6',right:'m9 6 6 6-6 6',reset:'M3 11a9 9 0 1 1 2.6 7M3 4v7h7',close:'m6 6 12 12M6 18 18 6',target:'M12 3a9 9 0 1 0 9 9M12 7a5 5 0 1 0 5 5M12 12l9-9M16 3h5v5',check:'m5 12 4 4L19 6',alert:'m12 3 10 18H2zM12 9v5M12 17v.1',comment:'M4 4h16v12H8l-4 4z',arrow:'M5 12h14m-5-5 5 5-5 5',clock:'M12 8v4l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.board}"/></svg>`;
function hydrateIcons(){ $$('[data-icon]').forEach(el => el.innerHTML = icon(el.dataset.icon)); }
const isoDate = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dateFrom = s => new Date(`${s}T12:00:00`);
const shiftDate = (s, amount) => {const d=dateFrom(s); d.setDate(d.getDate()+amount);return isoDate(d);};
const today = isoDate(new Date());
const STORAGE_KEY = 'quest-board-demo-v2';
const DEFAULT_PROCESSES=[{id:'hand-layup',name:'A320 hand layup',revision:1,productiveMinutes:240,rateMultiplier:1,stepMinutes:[45,30,60,45,60,30,45,60,30,45,60,30]},{id:'process-b',name:'Bonding process B',revision:1,productiveMinutes:240,rateMultiplier:1,stepMinutes:[30,60,45,60,30,90,45,60]}];
function upgradeState(data){
 const next={...data,version:3,processes:data.processes||structuredClone(DEFAULT_PROCESSES)};
 next.jobs=data.jobs.map(j=>{const process=next.processes.find(p=>p.id===j.processId)||next.processes[0];const steps=j.stepMinutes||Array.from({length:j.total},(_,i)=>process.stepMinutes[i]||45);return {...j,processId:j.processId||process.id,stepMinutes:[...steps],configRevision:j.configRevision||process.revision,rateMultiplier:j.rateMultiplier||1,productiveMinutes:j.productiveMinutes??steps.slice(j.start,j.goal).reduce((a,b)=>a+b,0),overtimeMinutes:j.overtimeMinutes||0,closed:j.closed??j.date<today};});
 next.history=data.history.map(h=>{const job=next.jobs.find(j=>j.job===h.job&&j.date===h.date&&j.shift===h.shift);return {...h,processId:h.processId||job?.processId||'hand-layup',operators:h.operators||job?.operators||'Not recorded',start:h.start??h.from,gap:h.to-h.goal,productiveMinutes:h.productiveMinutes??job?.productiveMinutes??0,overtimeMinutes:h.overtimeMinutes||0,closed:h.closed??h.date<today,stepMinutes:h.stepMinutes||job?.stepMinutes||[],configRevision:h.configRevision||1};});
 return next;
}
let storageAdapter;try{storageAdapter=QuestStorage.createAdapter(localStorage,STORAGE_KEY);}catch{storageAdapter=QuestStorage.createAdapter({getItem(){return null},setItem(){throw Error('Unavailable')}},STORAGE_KEY);}

function createSeed(){
 const rows=[
 ['2401','Panel assembly A','Cell 01','Alex Morgan, Sam Chen',2,8,6,12,'on-track','Material ready. Continuing the planned sequence.'],
 ['2402','Panel assembly B','Cell 02','Jordan Lee',3,7,5,10,'at-risk','Waiting for a tooling check before the next step.'],
 ['2403','Fairing assembly A','Cell 03','Taylor Reed, Casey Park',4,8,8,10,'on-track','Shift goal reached. Ready for the next handoff.'],
 ['2404','Panel assembly C','Cell 01','Riley Davis',1,6,3,12,'blocked','Material kit incomplete. Lead follow-up needed.'],
 ['2405','Fairing assembly B','Cell 02','Morgan Blake',2,6,5,8,'on-track','Paired training in progress. No blockers reported.'],
 ['2406','Panel assembly D','Cell 03','Jamie Brooks',6,10,10,10,'on-track','All sample steps complete. Handoff recorded.']
 ];
 const jobs=rows.map((r,i)=>({id:`job-${i}`,job:`DEMO-${r[0]}`,part:r[1],cell:r[2],operators:r[3],start:r[4],goal:r[5],end:r[6],total:r[7],status:r[8],comment:r[9],date:today,shift:'1',updatedAt:new Date(dateFrom(today).setHours(9,10+i*7)).toISOString()}));
 for(let day=1;day<=4;day++) for(let i=0;i<3;i++)jobs.push({...jobs[i],id:`past-${day}-${i}`,date:shiftDate(today,-day),end:Math.min(jobs[i].goal+(i===1?-1:0),jobs[i].total),updatedAt:new Date(dateFrom(shiftDate(today,-day)).setHours(14,30)).toISOString()});
 for(let i=0;i<2;i++)jobs.push({...jobs[i],id:`evening-${i}`,shift:'2',start:jobs[i].end,end:jobs[i].end,goal:jobs[i].total,status:'on-track',comment:'Example evening assignment. Awaiting shift handoff.'});
 const history=jobs.filter(j=>j.shift==='1').map((j,i)=>({id:`event-${i}`,at:j.updatedAt,date:j.date,shift:j.shift,cell:j.cell,job:j.job,part:j.part,from:j.start,to:j.end,goal:j.goal,total:j.total,status:j.status,comment:j.comment,kind:'Sample shift record'}));
 return upgradeState({version:2,jobs,history});
}
let state;
try{const saved=storageAdapter.load();state=[2,3].includes(saved?.version)&&Array.isArray(saved.jobs)&&Array.isArray(saved.history)?upgradeState(saved):createSeed();}catch{state=createSeed();}
let page='board',view='day',selectedDate=state.jobs.some(j=>j.date===today)?today:(state.jobs.map(j=>j.date).sort().at(-1)||today),selectedShift='1',selectedCell='all',tv=false,editingId=null,tvPage=0,selectedProcess='hand-layup',architectureLayer='input';
let beforeTv=null;
function saveState(){const result=storageAdapter.save(state);$('#save-status').textContent=result.saved?'Saved on this device':'Session only · storage unavailable';return result.saved;}
function statusOf(j){if(j.goal===j.start&&j.end<j.total)return j.status==='blocked'?'blocked':'no-target';if(j.end>=j.goal)return 'goal-met';if(j.closed)return 'behind';return j.status;}
const statusNames={'on-track':'In progress','at-risk':'At risk',blocked:'Blocked','goal-met':'Goal met',behind:'Below target','no-target':'No full step planned'};
const percent=j=>Math.round(j.end/j.total*100);
function weekDates(){const d=dateFrom(selectedDate);d.setDate(d.getDate()-((d.getDay()+6)%7));return Array.from({length:7},(_,i)=>shiftDate(isoDate(d),i));}
function filteredJobs(){const dates=view==='week'?weekDates():[selectedDate];return state.jobs.filter(j=>j.processId===selectedProcess&&dates.includes(j.date)&&(selectedShift==='all'||j.shift===selectedShift)&&(selectedCell==='all'||j.cell===selectedCell));}
function statValues(jobs){return {count:jobs.length,planned:jobs.filter(j=>j.goal>j.start).length,met:jobs.filter(j=>j.goal>j.start&&j.end>=j.goal).length,attention:jobs.filter(j=>['at-risk','blocked','behind'].includes(statusOf(j))).length,average:jobs.length?Math.round(jobs.reduce((a,j)=>a+percent(j),0)/jobs.length):0,target:jobs.length?Math.round(jobs.reduce((a,j)=>a+j.goal/j.total*100,0)/jobs.length):0};}
function renderMetrics(jobs){const s=statValues(jobs);$('#metrics').innerHTML=[['Jobs scheduled',s.count,'In the selected '+(view==='week'?'week':'shift'),'board',''],['Shift goals met',`${s.met}<small>/ ${s.planned}</small>`,'At or beyond the target step','target','good'],['Needs attention',s.attention,'Jobs with a reported delay','alert',s.attention?'warn':''],['Assembly progress',`${s.average}<small>%</small>`,'Average of step-based estimates','chart','']].map(([label,val,foot,ic,cl])=>`<div class="metric"><div class="metric-label">${label}${icon(ic)}</div><div class="metric-value">${val}</div><div class="metric-foot ${cl}">${foot}</div></div>`).join('');}
function card(j){const status=statusOf(j);const initials=j.operators.split(' ').map(s=>s[0]).slice(0,2).join('');const left=Math.max(0,j.goal-j.end);return `<article class="job-card"><div class="card-body"><div class="card-top"><span class="job-id">${esc(j.job)}</span><span class="status ${status}">${statusNames[status] || 'On track'}</span></div><h3>${esc(j.part)}</h3><div class="job-meta">${esc(j.cell)} <span>·</span> Shift ${esc(j.shift)}${j.overtimeMinutes?' · OT '+j.overtimeMinutes+'m':''}</div><div class="operator"><span class="operator-avatar">${esc(initials)}</span>${esc(j.operators)}</div><div class="step-track" aria-label="Start step ${j.start}, current step ${j.end}, goal step ${j.goal}"><div class="step"><span>${j.start}</span><small>Start</small></div><div class="step current"><span>${j.end}</span><small>Current / end</small></div><div class="step goal"><span>${j.goal}</span><small>Shift goal</small></div></div><div class="goal-strip"><span>${icon('target')}SHIFT TARGET</span><strong>${left?`${left} step${left===1?'':'s'} to goal`:'Shift goal achieved'}</strong></div><div class="card-note">${icon('comment')}<span>${esc(j.comment||'No shift notes yet.')}</span></div></div><div class="card-footer"><span>${percent(j)}% complete · gap ${j.end-j.goal>0?'+':''}${j.end-j.goal}</span><button class="text-button" data-edit="${esc(j.id)}" aria-label="Update ${esc(j.job)}">Update job ${icon('arrow')}</button></div></article>`;}
function renderSidebar(jobs){const s=statValues(jobs);return `<aside class="side-panel" aria-label="Assembly completion"><h2>Assembly completion</h2><div class="completion-card"><div class="completion-header"><span class="overline">AVERAGE COMPLETION</span>${icon('chart')}</div><div class="completion-total">${s.average}<small>%</small></div><div class="completion-caption">Across ${s.count} assignment${s.count===1?'':'s'} in this view</div><div class="target-comparison"><span>Target <strong>${s.target}%</strong></span><span>Gap <strong>${s.average-s.target>0?'+':''}${s.average-s.target} pp</strong></span></div><div class="overall-progress"><span style="width:${s.average}%"></span></div><div class="completion-bottom"><span>Unweighted steps</span><strong>${jobs.reduce((a,j)=>a+j.end,0)} / ${jobs.reduce((a,j)=>a+j.total,0)}</strong></div></div><div class="assembly-list">${jobs.length?jobs.map(j=>`<div class="assembly-row"><div class="assembly-label"><strong>${esc(j.job)}</strong><span>${percent(j)}%</span></div><small>${esc(j.cell)} · ${esc(j.part)}</small><div class="progress-bar" role="progressbar" aria-label="${esc(j.job)} assembly completion" aria-valuenow="${percent(j)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${percent(j)}%"></span></div></div>`).join(''):'<p class="form-hint">No jobs in this view.</p>'}</div><div class="handoff-note"><h3>${icon('comment')} A better shift handoff</h3><p>Leave an end step and a short note so the next shift knows where to pick up.</p></div></aside>`;}
function renderDayBoard(jobs){$('#page-content').innerHTML=`<div class="board-layout"><section><div class="section-top"><h2>${view==='week'?'This week':'Shift assignments'} <span class="count-pill">${jobs.length}</span></h2><div class="legend"><span><i></i>In progress</span><span><i class="amber"></i>At risk</span><span><i class="red"></i>Blocked</span></div></div><div class="job-grid">${jobs.map(card).join('')||'<div class="empty-state"><h3>A fresh board.</h3><p>No jobs match this date, shift, and work cell. Add an assignment or choose another view.</p><button class="button" data-action="today">Return to today</button></div>'}</div></section>${renderSidebar(jobs)}</div>`;}
function renderBase(){const titles={board:'Production board',history:'Shift history',insights:'Production insights',process:'Process setup',architecture:'System architecture'};$('#page-title').innerHTML=`${titles[page]}<span class="title-dot"></span>`;$('#breadcrumb-page').textContent=titles[page];$$('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});$$('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view));});$('#board-date').value=selectedDate;const jobs=filteredJobs();renderMetrics(jobs);if(page==='architecture')renderArchitecture();else if(page==='process')renderProcess();else if(page==='history')renderHistory(jobs);else if(page==='insights')renderInsights(jobs);else if(tv)renderTv(jobs);else if(view==='week')renderWeek(jobs);else renderDayBoard(jobs);$('#record-count').textContent=`${jobs.length} job${jobs.length===1?'':'s'} in this view`;hydrateIcons();}
function notify(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('visible'),3500);}
$('#shift-filter').addEventListener('change',e=>{selectedShift=e.target.value;render();});$('#cell-filter').addEventListener('change',e=>{selectedCell=e.target.value;render();});$('#board-date').addEventListener('change',e=>{if(e.target.value){selectedDate=e.target.value;render();}});$('#prev-date').onclick=()=>{selectedDate=shiftDate(selectedDate,view==='week'?-7:-1);render();};$('#next-date').onclick=()=>{selectedDate=shiftDate(selectedDate,view==='week'?7:1);render();};
document.addEventListener('click',e=>{if(e.target.closest('.brand')){page='board';render();}const v=e.target.closest('[data-view]');if(v){view=v.dataset.view;render();}const n=e.target.closest('[data-page]');if(n){page=n.dataset.page;render();window.scrollTo(0,0);}if(e.target.closest('[data-action="today"]')){selectedDate=today;render();}});

function shortDate(d,options={month:'short',day:'numeric'}){return dateFrom(d).toLocaleDateString('en-US',options);}
function renderWeek(jobs){const dates=weekDates().filter((d,i)=>i<5||jobs.some(j=>j.date===d)||d===selectedDate);$('#page-content').innerHTML=`<div class="section-top"><h2>Week of ${shortDate(dates[0])} <span class="count-pill">${jobs.length} assignments</span></h2><span class="secondary-text">Choose a job to update its shift</span></div><div class="week-grid" style="--days:${dates.length}">${dates.map(d=>{const daily=jobs.filter(j=>j.date===d);const met=daily.filter(j=>j.end>=j.goal).length;return `<section class="week-column ${d===today?'is-today':''}"><div class="week-heading"><span>${shortDate(d,{weekday:'short'}).toUpperCase()}</span><strong>${shortDate(d,{day:'numeric'})}</strong><small>${met} / ${daily.length} goals met</small></div><div class="week-jobs">${daily.map(j=>`<button class="week-job" data-edit="${esc(j.id)}" aria-label="Update ${esc(j.job)} on ${shortDate(d)}"><div class="job-id">${esc(j.job)}</div><h3>${esc(j.part)}</h3><div class="job-meta">${esc(j.cell)} · Shift ${j.shift}</div><p class="week-operators">${esc(j.operators)}</p><div class="week-steps"><span>Start <b>${j.start}</b></span><span>End <b>${j.end}</b></span><span>Goal <b>${j.goal}</b></span></div><div class="progress-bar"><span style="width:${percent(j)}%"></span></div><div class="week-status"><span class="status ${statusOf(j)}">${statusNames[statusOf(j)]}</span><small>${percent(j)}%</small></div></button>`).join('')||'<div class="week-empty">No assignments</div>'}</div></section>`;}).join('')}</div><p class="form-hint">Each card is a date-and-shift assignment. Example steps illustrate the concept and are not an approved production sequence.</p>`;}
function historyRows(){const dates=view==='week'?weekDates():[selectedDate];return state.history.filter(h=>h.processId===selectedProcess&&dates.includes(h.date)&&(selectedShift==='all'||h.shift===selectedShift)&&(selectedCell==='all'||h.cell===selectedCell)).sort((a,b)=>b.at.localeCompare(a.at));}
function historyStatus(h){return statusOf({...h,end:h.to,start:h.start??h.from});}
function renderHistory(){const rows=historyRows();$('#page-content').innerHTML=`<div class="section-top"><h2>Shift activity <span class="count-pill">${rows.length}</span></h2><button class="button" id="export-history">${icon('download')}Export CSV</button></div><div class="history-panel">${rows.length?rows.map(h=>`<article class="history-row"><div class="history-symbol">${icon(h.kind==='Job added'?'plus':'history')}</div><div class="history-detail"><div class="history-title"><strong>${esc(h.job)}</strong><span>${esc(h.kind)}</span><span class="status ${historyStatus(h)}">${statusNames[historyStatus(h)]}</span></div><p>${esc(h.part)} · ${esc(h.cell)} · Shift ${h.shift} · ${esc(h.operators)}</p><div class="history-steps">Step ${h.from} ${icon('arrow')} <strong>${h.to}</strong><span>Goal: ${h.goal} · Gap: ${h.gap>0?'+':''}${h.gap} · OT: ${h.overtimeMinutes}m</span></div><p class="history-note">${esc(h.comment||'No comment recorded.')}</p></div><time datetime="${esc(h.at)}">${shortDate(h.date)}<small>${new Date(h.at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</small></time></article>`).join(''):'<div class="empty-state"><h3>No shift activity yet.</h3><p>Updates for this date, shift, and work cell will appear here.</p></div>'}</div><p class="form-hint">Sample records are labeled. New updates preserve a snapshot of the goal, end step, status, and note on this device.</p>`;}
function renderInsights(jobs){const dates=view==='week'?weekDates():[selectedDate];const cells=['Cell 01','Cell 02','Cell 03'].filter(c=>selectedCell==='all'||c===selectedCell);$('#page-content').innerHTML=`<div class="insights-grid"><section class="insight-card"><div class="section-top"><h2>Goals reached by day</h2><span class="secondary-text">${view==='week'?'Selected week':'Selected day'}</span></div><div class="goal-chart">${dates.map(d=>{const rows=jobs.filter(j=>j.date===d&&j.goal>j.start),met=rows.filter(j=>j.end>=j.goal).length,pct=rows.length?Math.round(met/rows.length*100):0;return `<div class="chart-column"><strong>${rows.length?pct+'%':'—'}</strong><div class="chart-track"><div style="height:${pct}%"></div></div><span>${shortDate(d,{weekday:'short'})}</span><small>${met} / ${rows.length}</small></div>`;}).join('')}</div><p class="form-hint">Assignments at or beyond their saved shift goal. This measures goal attainment, not labor productivity.</p></section><section class="insight-card"><h2>Work-cell overview</h2><div class="cell-insights">${cells.map(cell=>{const rows=jobs.filter(j=>j.cell===cell),s=statValues(rows);return `<div class="cell-insight"><div><strong>${cell}</strong><span>${s.count} assignments</span></div><div class="cell-percentage">${s.average}%<small>avg. completion</small></div><div class="progress-bar"><span style="width:${s.average}%"></span></div><p><span>${s.met} goals met</span><span>${s.attention} need attention</span></p></div>`;}).join('')}</div></section><section class="insight-card attention-insight"><h2>Items to follow up</h2>${jobs.filter(j=>['blocked','at-risk','behind'].includes(statusOf(j))).map(j=>`<button class="attention-row" data-edit="${esc(j.id)}"><span class="status ${statusOf(j)}">${statusNames[statusOf(j)]}</span><div><strong>${esc(j.job)} · ${esc(j.cell)} · ${shortDate(j.date)} · Shift ${j.shift}</strong><p>${esc(j.comment||'No reason recorded.')}</p></div>${icon('right')}</button>`).join('')||'<p class="form-hint">No reported blockers or at-risk jobs in this view.</p>'}</section></div>`;}
function tvPageSize(){return Math.max(1,Math.min(window.innerWidth>=1600?6:3,Math.floor((window.innerHeight-405)/(window.innerWidth>=1600?115:95))));}
function renderTv(jobs){const size=tvPageSize(),pages=Math.max(1,Math.ceil(jobs.length/size));tvPage%=pages;const visible=jobs.slice(tvPage*size,tvPage*size+size);$('#page-content').innerHTML=`<div class="tv-board-layout"><section><div class="section-top"><h2>${shortDate(selectedDate,{weekday:'long',month:'long',day:'numeric'})} <span class="count-pill">${selectedShift==='all'?'All shifts':'Shift '+selectedShift}</span></h2><span class="tv-pagination">${pages>1?`Page ${tvPage+1} / ${pages} · 20s <button class="icon-button" id="next-tv-page" aria-label="Next TV page">${icon('right')}</button>`:'Shift assignments'}</span></div><div class="tv-table-scroll"><table class="tv-table"><thead><tr><th>Job / work cell</th><th>Operator(s)</th><th>Start</th><th>Goal</th><th>Actual</th><th>Gap</th><th>Status</th></tr></thead><tbody>${visible.map(j=>`<tr><td><strong>${esc(j.job)}</strong><small>${esc(j.cell)} · ${esc(j.part)}</small></td><td class="tv-person"><span>${esc(j.operators)}</span>${j.overtimeMinutes?`<small>+${j.overtimeMinutes} min overtime</small>`:''}</td><td>${j.start}</td><td class="tv-goal">${j.goal}</td><td class="tv-actual">${j.end}</td><td class="tv-gap ${j.end<j.goal?'negative':''}">${j.end>j.goal?'+':''}${j.end-j.goal}</td><td><span class="status ${statusOf(j)}">${statusNames[statusOf(j)]}</span></td></tr>`).join('')||'<tr><td colspan="7">No assignments in this view.</td></tr>'}</tbody></table></div><div class="tv-key"><span>Goal = calculated end-of-shift target</span><span>Gap = actual − goal</span><span>Below target turns red when a shift is finished.</span></div></section>${renderSidebar(jobs)}</div>`;}
function render(){renderBase();const subtitles={board:'A clear plan. A shared goal. Every shift.',history:'Every update, ready for the next handoff.',insights:'Understand the work. Spot what needs attention.',process:'A reusable board, driven by process timing.',architecture:'Current architecture hypothesis — subject to stakeholder validation.'};$('#page-subtitle').textContent=subtitles[page];$('#add-job').hidden=tv||page!=='board';$('#tv-toggle').hidden=page!=='board';$('.view-toggle').hidden=tv;const auxiliary=['process','architecture'].includes(page);$('#metrics').hidden=auxiliary;$('.board-toolbar').hidden=auxiliary;$('.page-footer').hidden=auxiliary;$('.eyebrow').textContent=state.processes.find(p=>p.id===selectedProcess)?.name.toUpperCase()||'QUEST';$('#prev-date').setAttribute('aria-label',view==='week'?'Previous week':'Previous day');$('#next-date').setAttribute('aria-label',view==='week'?'Next week':'Next day');if(tv)$('#page-title').textContent=state.processes.find(p=>p.id===selectedProcess).name+' · Production';document.title=`${tv?'TV display':{board:'Production board',history:'Shift history',insights:'Insights',process:'Process setup',architecture:'System architecture'}[page]} · QUEST`;}
function openJob(id=null){if(tv)return;editingId=id;const current=state.jobs.find(j=>j.id===id);const process=state.processes.find(p=>p.id===(current?.processId||selectedProcess));const j=current||{job:'',part:'',operators:'',cell:selectedCell==='all'?'Cell 01':selectedCell,date:selectedDate,shift:selectedShift==='all'?'1':selectedShift,start:0,end:0,status:'on-track',comment:'',processId:process.id,productiveMinutes:process.productiveMinutes,overtimeMinutes:0,closed:false,stepMinutes:[...process.stepMinutes],configRevision:process.revision,rateMultiplier:process.rateMultiplier};
 window.questEditingSequence={stepMinutes:[...j.stepMinutes],rateMultiplier:j.rateMultiplier,configRevision:j.configRevision};
 $('#dialog-title').textContent=current?j.job:'Add an assignment';$('#dialog-eyebrow').textContent='INPUT → AUTOMATIC GOAL → BOARD → HISTORY';
 const input=(name,label,value,type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" required ${extra}></label>`;
 const select=(name,label,options)=>`<label class="field">${label}<select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${j[name]===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
 $('#form-fields').innerHTML=`<div class="form-grid">${input('job','Job number',j.job,'text','maxlength="40"')}${input('part','Part / assembly',j.part,'text','maxlength="100"')}${input('operators','Operator name(s)',j.operators,'text','maxlength="160"')}${select('cell','Work cell',['Cell 01','Cell 02','Cell 03'].map(c=>[c,c]))}${input('date','Assignment date',j.date,'date')}${select('shift','Shift',[['1','Shift 1 · Day'],['2','Shift 2 · Evening']])}${select('processId','Process',state.processes.map(p=>[p.id,p.name]))}${input('start','Start step (completed)',j.start,'number','min="0" max="999" step="1"')}${input('productiveMinutes','Planned productive minutes',j.productiveMinutes,'number','min="0" max="1440" step="1"')}${input('overtimeMinutes','Extra productive minutes (overtime)',j.overtimeMinutes,'number','min="0" max="720" step="1"')}<div class="goal-preview field full" id="goal-preview" aria-live="polite"></div>${input('end','Current / actual end step',j.end,'number','min="0" max="999" step="1"')}${select('status','Reported shift status',[['on-track','In progress'],['at-risk','At risk'],['blocked','Blocked']])}<label class="checkbox-field full"><input type="checkbox" name="closed" ${j.closed?'checked':''}> Shift finished — treat the end step as final</label><label class="field full">Shift comments<textarea name="comment" maxlength="500" placeholder="What should the next shift know?">${esc(j.comment)}</textarea></label></div><p class="form-hint">Sample timings only. Goals include whole steps that fit the productive-time budget. Breaks are excluded from the entered minutes. This assignment retains its saved timing snapshot; choosing a process loads its current configuration.</p>`;
 $('#form-error').textContent='';$('#job-dialog').showModal();updateGoalPreview();hydrateIcons();}
function editorGoal(){const f=$('#job-form');return QuestEngine.calculateGoal({start:Number(f.elements.start.value),productiveMinutes:Number(f.elements.productiveMinutes.value),overtimeMinutes:Number(f.elements.overtimeMinutes.value),...window.questEditingSequence});}
function updateGoalPreview(){try{const result=editorGoal();$('#goal-preview').innerHTML=`<div><span>CALCULATED SHIFT GOAL</span><strong>Step ${result.goal} <small>/ ${result.total}</small></strong></div><p>${result.usedMinutes.toFixed(0)} of ${result.availableMinutes} productive minutes assigned<br>${result.remainingMinutes.toFixed(0)} minutes remain; partial steps are not counted.</p>`;$('#goal-preview').dataset.goal=String(result.goal);}catch(error){$('#goal-preview').innerHTML=`<p>${esc(error.message)}</p>`;}}
function validateJob(j){if(!j.job.trim()||!j.part.trim()||!j.operators.trim())return 'Add a job number, assembly, and operator name.';if(!/^\d{4}-\d{2}-\d{2}$/.test(j.date)||!Number.isFinite(dateFrom(j.date).getTime())||isoDate(dateFrom(j.date))!==j.date)return 'Choose a valid assignment date.';if(!['1','2'].includes(j.shift)||!['Cell 01','Cell 02','Cell 03'].includes(j.cell)||!['on-track','at-risk','blocked'].includes(j.status))return 'Choose valid shift, work-cell, and status options.';if(![j.start,j.end,j.goal,j.total].every(n=>Number.isInteger(n)&&n>=0&&n<=999)||j.total<1)return 'Steps must be whole numbers; total steps must be at least 1.';if(j.end<j.start)return 'The end step cannot be before the start step.';if(j.goal<j.start)return 'The shift goal cannot be before the start step.';if(Math.max(j.start,j.end,j.goal)>j.total)return 'Start, end, and goal steps cannot exceed total assembly steps.';if(state.jobs.some(other=>other.id!==j.id&&other.job.toLowerCase()===j.job.toLowerCase()&&other.date===j.date&&other.shift===j.shift))return 'This job already has an assignment for the same date and shift.';return '';}
function submitJob(e){e.preventDefault();const raw=Object.fromEntries(new FormData(e.currentTarget));const prev=state.jobs.find(j=>j.id===editingId);let calculated;try{calculated=editorGoal();}catch(error){$('#form-error').textContent=error.message;return;}
 const j={...raw,...window.questEditingSequence,id:editingId||crypto.randomUUID(),start:Number(raw.start),end:Number(raw.end),goal:calculated.goal,total:calculated.total,productiveMinutes:Number(raw.productiveMinutes),overtimeMinutes:Number(raw.overtimeMinutes),closed:raw.closed==='on',job:raw.job.trim(),part:raw.part.trim(),operators:raw.operators.trim(),comment:raw.comment.trim(),updatedAt:new Date().toISOString()};const error=validateJob(j);if(error){$('#form-error').textContent=error;return;}if(prev)state.jobs=state.jobs.map(old=>old.id===j.id?j:old);else state.jobs.push(j);
 state.history.unshift(QuestStorage.historySnapshot(j,prev,prev?'Job updated':'Job added',j.updatedAt,crypto.randomUUID()));selectedDate=j.date;selectedShift=j.shift;selectedProcess=j.processId;$('#shift-filter').value=j.shift;$('#process-filter').value=j.processId;if(selectedCell!=='all'&&selectedCell!==j.cell){selectedCell=j.cell;$('#cell-filter').value=j.cell;}const persisted=saveState();$('#job-dialog').close();render();notify(persisted?'Goal calculated · job and history saved':'Updated for this session · storage unavailable');}
function toggleTv(){tv=!tv;document.body.classList.toggle('tv-mode',tv);$('#tv-label').textContent=tv?'Exit TV display':'TV display';if(tv){beforeTv={page,view};page='board';view='day';tvPage=0;}else if(beforeTv){page=beforeTv.page;view=beforeTv.view;}render();window.scrollTo(0,0);}
function exportHistory(){const fields=['Assignment date','Shift','Cell','Job','Assembly','Update type','Previous step','End step','Goal','Total steps','Status','Operator(s)','Start step','Gap','Productive minutes','Overtime minutes','Shift finished','Process','Timing revision','Comment','Recorded at'];const protect=v=>{let s=String(v??'');if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=historyRows().map(h=>[h.date,h.shift,h.cell,h.job,h.part,h.kind,h.from,h.to,h.goal,h.total,statusNames[historyStatus(h)],h.operators,h.start,h.gap,h.productiveMinutes,h.overtimeMinutes,h.closed,h.processId,h.configRevision,h.comment,h.at]);const blob=new Blob(['\uFEFF'+[fields,...rows].map(r=>r.map(protect).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`quest-shift-history-${selectedDate}.csv`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Shift history exported');}
$('#add-job').onclick=()=>openJob();$('#job-form').addEventListener('submit',submitJob);$('#close-dialog').onclick=()=>$('#job-dialog').close();$('#tv-toggle').onclick=toggleTv;$('#reset-demo').onclick=()=>$('#reset-dialog').showModal();$('#cancel-reset').onclick=()=>$('#reset-dialog').close();$('#confirm-reset').onclick=()=>{state=createSeed();selectedProcess='hand-layup';$('#process-filter').value=selectedProcess;selectedDate=today;selectedShift='1';selectedCell='all';page='board';view='day';$('#shift-filter').value='1';$('#cell-filter').value='all';saveState();$('#reset-dialog').close();render();notify('Demo data restored');};
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit]');if(edit)openJob(edit.dataset.edit);if(e.target.closest('#export-history'))exportHistory();if(e.target.closest('#next-tv-page')){tvPage++;render();}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&tv)toggleTv();});
window.addEventListener('storage',e=>{if(e.key!==STORAGE_KEY||!e.newValue)return;try{const next=JSON.parse(e.newValue);if([2,3].includes(next.version)&&Array.isArray(next.jobs)&&Array.isArray(next.history)){state=upgradeState(next);render();}}catch{}});
window.addEventListener('resize',()=>{if(tv)render();});
setInterval(()=>{if(tv){tvPage++;render();}},20000);
// Browser-agent access uses the same views as the visible controls.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_production_board',title:'Read the production board',description:'Read fictional demo assignments in the current date, shift, and work-cell view.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('No input fields are accepted.');const jobs=filteredJobs();return {date:selectedDate,view,shift:selectedShift,cell:selectedCell,jobs:jobs.map(j=>({id:j.id,job:j.job,part:j.part,start:j.start,end:j.end,goal:j.goal,completion:percent(j),status:statusOf(j)})),summary:statValues(jobs)};}});register({name:'start_job_update',title:'Open a job update',description:'Open the supervisor form for a demo assignment. Does not save changes; the user can review and save in the form.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='id')||typeof input.id!=='string'||!state.jobs.some(j=>j.id===input.id))throw new Error('Unknown assignment.');if(tv)throw new Error('Exit TV display before opening an update.');openJob(input.id);return {opened:true,id:input.id,saved:false};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

function renderProcess(){const p=state.processes.find(p=>p.id===selectedProcess);$('#page-content').innerHTML=`<div class="configuration-banner"><span class="status at-risk">Sample timings</span><p>Replace these examples with approved process standards before using calculated goals for production.</p></div><section class="process-panel"><form id="process-form"><div class="section-top"><h2>Process configuration</h2><span class="count-pill">Revision ${p.revision}</span></div><div class="form-grid"><label class="field">Process<select id="config-process">${state.processes.map(process=>`<option value="${process.id}" ${process.id===selectedProcess?'selected':''}>${esc(process.name)}</option>`).join('')}</select></label><label class="field">Display name<input name="name" value="${esc(p.name)}" required maxlength="60"></label><label class="field">Default productive minutes<input name="productiveMinutes" type="number" min="0" max="1440" step="1" required value="${p.productiveMinutes}"></label><label class="field">Timing rate multiplier (1 = standard)<input name="rateMultiplier" type="number" min="0.1" max="10" step="0.1" required value="${p.rateMultiplier}"></label><label class="field">Number of sequential steps<input id="config-step-count" type="number" min="1" max="50" step="1" value="${p.stepMinutes.length}" required></label></div><div class="timing-header"><h3>Expected duration per step</h3><span>Minutes · sequential, whole-step completion</span></div><div id="timing-fields" class="timing-grid">${p.stepMinutes.map((duration,i)=>timingField(i,duration)).join('')}</div><p class="form-hint">A rate of 1 uses the duration as entered. A rate of 2 halves the time required per step. The demo does not infer an operator's speed. Existing assignments and history keep their timing snapshots; new assignments use this revision.</p><p class="form-error" id="config-error" role="alert"></p><div class="config-footer"><span>Final-step completion is a demo rule pending stakeholder validation.</span><button class="button primary" type="submit">Save configuration</button></div></form></section><div class="engine-explainer"><div><span class="eyebrow">GOAL ENGINE</span><h2>Time budget → expected end step</h2><p>Start at the last completed step. Add productive shift minutes and overtime. Walk the configured sequence, counting only steps that fit within that budget.</p></div><div class="formula">Start step + whole steps that fit<br><strong>= calculated goal step</strong></div></div>`;}
function timingField(i,duration){return `<label class="timing-field"><span>Step ${i+1}</span><input name="duration" type="number" min="1" max="10000" step="1" value="${duration}" required aria-label="Step ${i+1} duration in minutes"><small>min</small></label>`;}
function saveProcess(e){e.preventDefault();const form=e.target;const p=state.processes.find(p=>p.id===selectedProcess);const next={...p,name:form.elements.name.value.trim(),productiveMinutes:Number(form.elements.productiveMinutes.value),rateMultiplier:Number(form.elements.rateMultiplier.value),stepMinutes:$$('[name="duration"]',form).map(el=>Number(el.value)),revision:p.revision+1};try{QuestEngine.validateTimings(next.stepMinutes);if(!next.name||!Number.isFinite(next.productiveMinutes)||next.productiveMinutes<0||!Number.isFinite(next.rateMultiplier)||next.rateMultiplier<=0)throw Error('Enter a name, a valid time budget, and a positive rate.');}catch(error){$('#config-error').textContent=error.message;return;}state.processes=state.processes.map(old=>old.id===next.id?next:old);const saved=saveState();renderProcessChoices();render();notify(saved?'Configuration saved · existing records preserved':'Configuration updated for this session only');}
function renderProcessChoices(){$('#process-filter').innerHTML=state.processes.map(p=>`<option value="${esc(p.id)}" ${p.id===selectedProcess?'selected':''}>${esc(p.name)}</option>`).join('');}
const architectureLayers={
 input:{number:'01',name:'User input',tag:'Working in demo',icon:'plus',summary:'Lead / supervisor → controlled form',detail:'Leads enter the production information they already manage. The form validates step ranges and duplicate job/date/shift assignments before anything is saved.',fields:['Date, shift, operator(s), work cell','Job ID, part / assembly, process','Start and actual end step','Productive time, overtime, comments','Shift finished / reported blocker'],boundary:'Names are fictional in this demo. Permitted identity visibility and comparisons require stakeholder agreement.'},
 logic:{number:'02',name:'Goal engine',tag:'Working in demo',icon:'target',summary:'Process timings → goal, actual, gap',detail:'A pure calculation module walks the selected process sequence from the start step. It consumes productive minutes plus overtime and calculates the last whole step that fits.',fields:['Goal = expected last completed step','Gap = actual end − goal','Completion = completed steps / total','Goal met and unit complete are distinct','Timing snapshots preserve past calculations'],boundary:'Sample timing rules only. TAC interpretation, breaks, parallel work, rework, and final acceptance rules remain open decisions.'},
 board:{number:'03',name:'Production board',tag:'Working in demo',icon:'board',summary:'HTML / CSS / JavaScript interface',detail:'One board engine displays records from configurable processes. The supervisor sees day/week views, controlled editing, target gaps, and status colors.',fields:['Supervisor view: enter, review, update','TV view: large text and few controls','Progress and target shown together','Color labels remain readable without color','No direct SAP or ERP connection'],boundary:'A TV presentation is not an access-control boundary. A deployed system needs approved permissions and a secured shop-floor device.'},
 data:{number:'04',name:'Data access & history',tag:'Local demo adapter',icon:'history',summary:'Structured records → saved snapshots',detail:'A separate storage adapter reads and writes production records. Each update captures a history snapshot including operators, date, shift, target, actual end, gap, overtime, and timing revision.',fields:['Prototype: device-local browser storage','Proposed: ST-approved shared data source','Candidates: SharePoint / OneDrive / files','Supervisor history and trend views','CSV export for review and later analytics'],boundary:'Shared persistence, concurrent updates, backups, access controls, and retention are not implemented in the demo. The IT-approved storage choice remains open.'}
};
function renderArchitecture(){const active=architectureLayers[architectureLayer];$('#page-content').innerHTML=`<div class="architecture-status"><span class="hypothesis-badge">ARCHITECTURE HYPOTHESIS</span><p>Working demo modules and proposed deployment boundaries.</p></div><div class="environment-boundary"><div class="environment-heading">${icon('layers')}<div><strong>Proposed ST-approved environment</strong><span>SharePoint or local network · hosting and data location to be validated by ST IT</span></div><span class="boundary-label">INTERNAL BOUNDARY</span></div><div class="architecture-flow">${Object.entries(architectureLayers).map(([key,l])=>`<button class="architecture-node ${key===architectureLayer?'selected':''}" data-layer="${key}" aria-pressed="${key===architectureLayer}"><span class="node-top"><span>${l.number}</span>${icon(l.icon)}</span><strong>${l.name}</strong><p>${l.summary}</p><small>${l.tag}</small></button>`).join('')}</div><div class="architecture-support"><div class="support-card"><span class="support-link">CONFIGURATION → GOAL ENGINE</span><h3>Process definition</h3><p>Sequence order · expected duration · rate · default productive time</p><button class="text-button" data-page="process">Open sample process setup ${icon('arrow')}</button></div><div class="support-card"><span class="support-link">STORAGE ↔ BOARD / ANALYTICS</span><h3>Approved shared repository</h3><p>Production records + append-only history proposed. SharePoint, OneDrive, Excel, or local files are candidates to evaluate.</p><span class="proposed-label">Proposed · not connected</span></div></div><div class="flow-caption">Lead input → calculate → validate and store → render board / TV → review history</div></div><div class="architecture-bottom"><section class="layer-detail"><div class="section-top"><h2>${active.number} / ${active.name}</h2><span class="status">${active.tag}</span></div><p>${active.detail}</p><div class="layer-fields">${active.fields.map(f=>`<div>${icon('check')}<span>${f}</span></div>`).join('')}</div><div class="decision-note">${active.boundary}</div></section><aside class="external-boundaries"><h2>Outside this MVP</h2><div>${icon('close')}<span><strong>SAP / ERP / future MPP</strong><small>No direct integration in this prototype</small></span></div><div>${icon('close')}<span><strong>Public internet</strong><small>No runtime dependency; all assets are local</small></span></div><p>Potential future integration requires a separate scope and approval. No manufacturing data is sent to an external service by this application.</p></aside></div><section class="constraints-panel"><h2>Constraints that shape the design</h2><div class="constraint-grid"><div><strong>Union / workforce rules</strong><span>Validate names, history, and permitted comparisons.</span></div><div><strong>GCC High / FedRAMP</strong><span>Validate applicable requirements and approved environment with ST IT.</span></div><div><strong>Proprietary data</strong><span>Fictional records now; approved internal handling later.</span></div><div><strong>User simplicity</strong><span>Short forms, clear states, readable TV output.</span></div><div><strong>Hard to break</strong><span>Controlled fields, calculated targets, stable layouts.</span></div><div><strong>Long-term scalability</strong><span>Process configuration + replaceable storage adapter.</span></div></div></section>`;}
$('#process-filter').addEventListener('change',e=>{selectedProcess=e.target.value;tvPage=0;render();});
$('#job-form').addEventListener('input',e=>{if(['start','productiveMinutes','overtimeMinutes'].includes(e.target.name))updateGoalPreview();});
$('#job-form').addEventListener('change',e=>{if(e.target.name==='processId'){const p=state.processes.find(p=>p.id===e.target.value);window.questEditingSequence={stepMinutes:[...p.stepMinutes],rateMultiplier:p.rateMultiplier,configRevision:p.revision};$('#job-form').elements.productiveMinutes.value=p.productiveMinutes;updateGoalPreview();}});
document.addEventListener('change',e=>{if(e.target.id==='config-process'){selectedProcess=e.target.value;renderProcessChoices();render();}if(e.target.id==='config-step-count'){const count=Number(e.target.value);if(Number.isInteger(count)&&count>=1&&count<=50){const old=$$('[name="duration"]',$('#process-form')).map(i=>Number(i.value));$('#timing-fields').innerHTML=Array.from({length:count},(_,i)=>timingField(i,old[i]||45)).join('');}}});
document.addEventListener('submit',e=>{if(e.target.id==='process-form')saveProcess(e);});document.addEventListener('click',e=>{const layer=e.target.closest('[data-layer]');if(layer){architectureLayer=layer.dataset.layer;renderArchitecture();hydrateIcons();}});
renderProcessChoices();render();saveState();
